INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-25','Active','2022-12-01T18:44:11.000+0000','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Missing Documents</strong></p><p><br></p><p><span style="font-size: 16px;">Please email your missing documents to </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">international@stthomas.edu</a><span style="font-size: 16px;">. To view required documents, visit the </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/index.html" target="_blank" style="font-size: 16px;">International Admissions website</a><span style="font-size: 16px;">. </span></p><p><br></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68); font-size: 16px;">Missing documents can also be mailed to: </span></p><p><br></p><p><span style="font-size: 16px;">University of St. Thomas</span></p><p><span style="font-size: 16px;">Office of International Students &amp; Scholars</span></p><p><span style="font-size: 16px;">Mail 5014</span></p><p><span style="font-size: 16px;">2115 Summit Avenue</span></p><p><span style="font-size: 16px;">St. Paul, MN 55105-1096</span></p><p><br></p><p><span style="font-size: 16px;">We will accept unofficial transcripts for your application. Students must have official transcripts upon arrival to St. Thomas. </span></p>','International','ApplicationPortal','Started App;Submitted App;Temporary Hold','','','','','','','','2023-07-20T23:46:45.000+0000','Submit Missing Docs INTL (UGFR)','UGFRSubmitMissingDocssINTL','','20.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-10');
