color: #6d3696;

font-weight: 100;

z-index: -1;

display: inline-flex;

animation: secondspan 1.5s forwards cubic-bezier(0.785, 0.135, 0.15, 0.86);

}



@keyframes fadeIn{



0%{

opacity: 0;

transform: scale(0);

}



50%{

opacity: 1;

transform: scale(1);

}



0%{

opacity: 1;

transform: scale(0.5);

}



}





@keyframes secondspan{



0%{

transform: translateX(-100%);

}



60%{

transform: translateX(-100%);

}



100%{

transform: translateX(0%);

}



}







</style>','','','','Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-10');
