INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-49','Active','2022-09-28T16:14:34.000+0000','','<p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Admission Decision Timeline</strong></p>','','ApplicationPortal','Complete App;File Hold;Pending;Denied','','','','','','','','2023-07-20T23:14:26.000+0000','Admissions Decisions Dates (UGFR)','UGFRAdmissionsDecisionsDates','<style>

    .lineUST {

        border-bottom: 5px solid #5f19a0;

        margin-top: 5px;

        margin-bottom: 4px;

        width: 100%;

    }



</style>

<div class="lineUST"></div>









<div class="hwrapUST"><div class="hmoveUST">

<div class="hslideUST">

<div class="dynamic-txtsUST"><h3><i>Domestic First-Year</i></h3>

<div class="animationUST">

<br>

<p><span class="firstUST"><b>By December 15</b></span>

<span class="slideUST">

<p><span class="secondUST">If applied by November 1</p></p><br>

<p><span class="firstUST"><b>By February 15</b></span></span>

<span class="slideUST">

<p><span class="secondUST">If applied by January 15</p></p></span></span><br>

<p><span class="firstUST"><b>After February 15</b></span>

<span class="slideUST"> 

<p><span class="secondUST">Decisions are made on a rolling basis. Usually, you’ll hear back from us within 2-3 weeks of submitting all required documents.</p></p></span></span>

</div>

</div>

</div>



<div class="hslideUST">

<div class="dynamic-txtsUST"><h3><i>International First-Year</i></h3>

