INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-75','Active','2023-01-25T17:12:00.000+0000','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Thank you for submitting your St. Thomas transfer application!</strong></p><p><br></p><p><span style="font-size: 16px;">To complete the application process, you must send high school transcripts, and college transcripts from all institutions you have attended, and complete the </span><a href="https://www.stthomas.edu/_media-library/_documents/main/stthomas-ens-code-of-conduct-form.pdf" target="_blank" style="font-size: 16px;">Code of Conduct Form</a><span style="font-size: 16px;">.</span></p><p><br></p><p><span style="font-size: 16px;">We will accept unofficial transcripts for your application. You may submit an unofficial transcript by downloading it from your school system and sending it to </span><a href="mailto:admissions@stthomas.edu" target="_blank" style="font-size: 16px;">admissions@stthomas.edu</a><span style="font-size: 16px;"> or your admissions counselor. </span><strong style="font-size: 16px;">Official transcripts will be required before the start of the term</strong><span style="font-size: 16px;">.</span></p><p><br></p><p><span style="color: rgb(68, 68, 68); background-color: rgb(255, 255, 255); font-size: 16px;">Your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="background-color: rgb(255, 255, 255); font-size: 16px;">admissions counselor</a><span style="background-color: rgb(255, 255, 255); font-size: 16px; color: rgb(68, 68, 68);"> is here to help as you navigate the application process. Contact them to ask any questions.</span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationPortal','Submitted App','','','','','','','','2023-07-20T22:35:20.000+0000','UG Submitted (UGTR)','UGTRSubmitted','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-7');
