.confetti {

width: 8px;

height: 12px;

background-color: #f2d74e;

position: absolute;

left: 50%;

animation: confetti 5s ease-in-out -2s infinite;

transform-origin: top;

overflow: hidden;

}

.confetti:nth-child(1) {

background-color: #f2d74e; bottom: 96%; left: 15%; animation-delay: -0.5s;

}

.confetti:nth-child(2) {

