INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-83','Active','2023-01-25T17:49:10.000+0000','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Missing Documents</strong></p><p><br></p><p><span style="font-size: 16px;">Please email your missing documents to </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">international@stthomas.edu</a><span style="font-size: 16px;">. To view required documents, visit the International Admissions </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/index.html" target="_blank" style="font-size: 16px;">website</a><span style="font-size: 16px;">.</span></p><p><br></p><p><span style="color: rgb(68, 68, 68); font-size: 16px;">Missing documents can also be mailed to:</span></p><p><br></p><p><span style="font-size: 16px;">University of St. Thomas</span></p><p><span style="font-size: 16px;">Office of International Students &amp; Scholars</span></p><p><span style="font-size: 16px;">Mail 5014</span></p><p><span style="font-size: 16px;">2115 Summit Avenue</span></p><p><span style="font-size: 16px;">St. Paul, MN 55105-1096</span></p><p><br></p><p><span style="font-size: 16px;">We will accept unofficial transcripts for your application. Students must have official transcripts upon arrival to St. Thomas.</span></p>','International','ApplicationPortal','Started App;Submitted App;Temporary Hold','','','','','','','','2023-01-27T18:23:12.000+0000','Submit Missing Docs INTL (UGTR)','UGTRSubmitMissingDocssINTL','','20.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-7');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-84','Active','2023-01-25T17:51:35.000+0000','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Thank you for submitting your application to St. Thomas!</strong></p><p><br></p><p><span style="color: rgb(37, 36, 35); font-size: 16px;">Your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="color: rgb(91, 95, 199); font-size: 16px; background-color: rgb(255, 255, 255);">admissions counselor</a><span style="color: rgb(37, 36, 35); font-size: 16px;"> is here to help as you navigate the application process. Contact them to ask any questions.</span></p>','International','ApplicationPortal','Submitted App;Temporary Hold','','','','','','','','2023-01-27T18:24:27.000+0000','UG Submitted INTL (UGTR)','UGTRSubmittedINTL','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-7');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-85','Active','2023-02-07T15:45:54.000+0000','','<p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Fall Transfer Timeline</strong></p>','','ApplicationPortal','Submitted App;Complete App;File Hold;Pending;Admit;Confirmed','','','','','','','Fall 2023','2023-07-20T22:34:48.000+0000','Admissions Decisions Dates-NoSlide (UGTR)','UGTRAdmissionsDecisionsDates','<style>

