INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-95','Inactive','2022-08-02T03:50:44.000+0000','','<p style="text-align: center;"><strong style="font-size: 14px; background-color: rgb(255, 255, 255); color: rgb(173, 28, 205);">Applying for Undergraduate Admissions? </strong><strong style="font-size: 14px; color: rgb(173, 28, 205);">The Fall 2022 application is available NOW!</strong></p><p><br></p><p><span style="font-size: 14px;">There are no application fees to apply and we offer the </span><span style="font-size: 14px; color: rgb(173, 28, 205);">St. Thomas</span><span style="font-size: 14px;"> application or the Common Application.</span></p><p><br></p><p><br></p><p style="text-align: center;"><span style="font-size: 14px; color: rgb(173, 28, 205);"> </span><span style="font-size: 14px; background-color: rgb(255, 255, 255); color: rgb(173, 28, 205);">Applying for Dougher<span class="ql-cursor"></span>ty Family College 2-year program?</span></p><p><br></p><p><span style="font-size: 14px;">The Dougherty Family College is a selective 2-year program offered at the University of St. Thomas. Acting as an eventual pathway to a 4-year degree, </span><a href="https://dfc.stthomas.edu/" target="_blank" style="font-size: 14px; background-color: rgb(255, 255, 255);">https://dfc.stthomas.edu/</a>. <span style="font-size: 14px;">Dougherty Family College is designed to serve student populations with high financial need (as determined by FAFSA) and provides a supportive learning environment to recent high school graduates who have shown strong academic success and college-readiness but may benefit from additional supports and resources.</span></p><p><br></p><p><span style="font-size: 14px;">Applications are reviewed on a rolling basis—meaning we will review applications and admit students based on available space in our class. Don’t wait; apply today! </span></p><p><br></p><p style="text-align: center;"><br></p><p style="text-align: center;"><strong>Visit</strong></p><p style="text-align: center;"><a href="https://www.stthomas.edu/admissions/undergraduate/campus-visits" target="_blank" style="font-size: 14px; background-color: rgb(255, 255, 255);">https://www.stthomas.edu/admissions/undergraduate/campus-visits</a></p><p><br></p><p style="text-align: center;"><strong style="font-size: 14px; background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">Meet your admissions counselor</strong></p><p style="text-align: center;"><a href="https://www.stthomas.edu/admissions/undergraduate/contact/locate-counselor" target="_blank" style="font-size: 14px; background-color: rgb(255, 255, 255);">https://www.stthomas.edu/admissions/undergraduate/contact/locate-counselor</a></p><p><br></p><p style="text-align: center;"><strong style="background-color: rgb(255, 255, 255); font-size: 14px; color: rgb(68, 68, 68);">Why St. Thomas</strong></p><p><a href="https://www.stthomas.edu/admissions/undergraduate/post-graduation" target="_blank" style="font-size: 14px; background-color: rgb(255, 255, 255);">https://www.stthomas.edu/admissions/undergraduate/post-graduation</a></p><p><br></p><p style="text-align: center;"><strong style="background-color: rgb(255, 255, 255); font-size: 14px; color: rgb(68, 68, 68);">Explore our majors and minors</strong></p><p><a href="https://www.stthomas.edu/academics/undergraduate" target="_blank" style="font-size: 14px; background-color: rgb(255, 255, 255);">https://www.stthomas.edu/academics/undergraduate</a></p>','','ApplicationCreate','','','','','','','','','2022-08-02T03:50:44.000+0000','Graphic: UG Inquiry (UGTR)','','','7.0','','','Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-7');
