INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-101','Active','2022-08-02T03:50:44.000+0000','','<p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Welcome to the International Transfer Application!</strong></p><p><br></p><p>Thank you for beginning your application. <span style="color: rgb(68, 68, 68);">Use the Application Portal above to follow the steps to submit your application. For questions, contact your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="background-color: rgb(255, 255, 255);">admissions counselor</a>. You can find more details on the <a href="https://www.stthomas.edu/admissions/international-students/application-information/" target="_blank">International Admissions website</a>.</p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Application Timelines</strong></p><p><span style="color: rgb(68, 68, 68);">All international student applications are reviewed on a rolling basis. Admission decisions will generally be issued within two weeks of receiving a complete application.</span></p>','International','ApplicationPortal','Started App','','','','','','','','2023-01-25T17:59:14.000+0000','Graphic: UG Started INTL (UGTR)','GraphicUGStartedNTLUGTR','','2.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-7');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-102','Active','2022-08-02T03:50:44.000+0000','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations on your acceptance </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">to the University of St. Thomas!</strong><span style="font-size: 20px; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Keep an eye on your mailbox because you&#39;ll soon be receiving an enrollment guide that details the next steps of the enrollment process. </span></p><p><br></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">Confirming Deposit</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">If you&#39;ve decided to attend St. Thomas for </span><strong style="font-size: 16px; color: rgb(33, 33, 33);">fall 2023</strong><span style="font-size: 16px; color: rgb(33, 33, 33);">, a $200 confirming deposit reserves your spot in the class. </span></p><p><br></p><p><span style="font-size: 16px; background-color: rgb(255, 255, 255);">﻿Select &quot;Submit Deposit&quot; above and follow the instructions to let us know you plan to be a Tommie!</span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">Course Registration</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Fall registration will open for new transfer students in early May. Information will be sent via email from our Academic Counseling office regarding that process. You must submit your $200 confirming deposit to register for spring classes </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">On-Campus Housing</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">If you will be living on campus, you’re required to submit a $200 housing deposit. Housing availability is not guaranteed and is based on the date we receive your housing deposit. All incoming transfer students with fewer than two semesters of college are required to meet the on-campus residency requirement. More information on this policy and other important housing information can be found on Residence Life&#39;s webpage </span><a href="https://www.stthomas.edu/tr/visit/" target="_blank" style="font-size: 16px; color: rgb(29, 117, 204);"><u>for transfer students.</u></a><span style="font-size: 16px;"> </span></p><p><span style="font-size: 11pt;"> </span></p><p><strong style="font-size: 12pt; color: rgb(109, 54, 150);">Admitted Student Website</strong><span style="font-size: 12pt; color: rgb(109, 54, 150);"> </span></p><p><span style="font-size: 16px; color: rgb(33, 33, 33);">Visit our </span><a href="https://www.stthomas.edu/admissions/undergraduate/transfer/admitted-students/index.html" target="_blank" style="font-size: 16px; color: rgb(29, 117, 204);"><u>transfer admitted students</u></a><span style="font-size: 16px; color: rgb(33, 33, 33);"> page to claim your St. Thomas account, activate your St. Thomas email address and learn about our deposit refund policies. </span></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationPortal','Admit','','','','','','','','2023-06-13T22:36:13.000+0000','Graphic: UG Admit (UGTR)','UGTRPreDepositAdmit','<div class="USTLine"></div>



