INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-118','Active','2023-02-01T23:14:42.000+0000','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Welcome to the School of Nursing</strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Mentor Program Application!</strong></p><p style="text-align: center;"><br></p><p><strong style="font-size: 16px; color: rgb(0, 0, 0);">Mentors:</strong></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Thank you for your interest in serving as a volunteer mentor to pre-licensure student(s) enrolled in the Susan S. Morrison School of Nursing at the University of St. Thomas. To best match our students to mentors, please submit the following application.</span></p><p><br></p><p><span style="font-size: 16px; color: rgb(0, 0, 0);">Please note: All mentors for this program must be a licensed RN.</span></p><p><br></p><p><strong style="font-size: 16px; color: rgb(0, 0, 0);">Mentees (Current Students):</strong></p><p><span style="font-size: 16px;">Thank you for your interest in connecting with a professional RN and volunteer mentor with the Susan S. Morrison School of Nursing at the University of St. Thomas. To best match you with an available mentor, please submit the following application. </span></p><p><br></p><p><em style="font-size: 16px;">Please use your St. Thomas (non-vanity) email address for your application: </em><a href="mailto:username@stthomas.edu" target="_blank" style="font-size: 16px;"><em>username@stthomas.edu</em></a><em style="font-size: 16px;">. Ex: </em><a href="mailto:xxxx0001@stthomas.edu" target="_blank" style="font-size: 16px;"><em>xxxx0001@stthomas.edu</em></a><em style="font-size: 16px;">.</em></p>','','ApplicationCreate;ApplicationRegistration','','','','','','','','','2023-02-01T23:14:42.000+0000','Welcome (SONMENTOR)','','','0.0','','','Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-25');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-119','Active','2023-02-01T23:15:55.000+0000','Status: Submitted','<p style="text-align: center;"><strong style="color: rgb(112, 48, 160); font-size: 20px;">Thank you for submitting your online application.</strong></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Student Success Director.</span></p>','','ApplicationPortal','Submitted App;Complete App;File Hold','','','','','','','','2023-02-01T23:15:55.000+0000','Graphic: GR View Submitted (SONMENTOR)','','','1.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-25');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-120','Active','2023-02-01T23:20:43.000+0000','','<p><strong style="font-size: 20px; color: rgb(109, 54, 150);">Student Success Director</strong></p><p><span style="color: rgb(0, 0, 0);">Jessica Nelson</span></p><p><a href="mailto:jessica.nelson@stthomas.edu" target="_blank">jessica.nelson@stthomas.edu</a></p><p><br></p><p>Please don&#39;t hesitate to reach out with a question. </p>','','ApplicationPortal;ApplicationCreate;ApplicationRegistration;ApplicationRequirement','','','','','','','','','2023-02-02T16:06:28.000+0000','Director Contact Info (SONMENTOR)','','','2.0','','','Left','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-25');
