INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-159','Active','2022-08-02T03:50:44.000+0000','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Your application is complete! </strong></p><p><br></p><p>Thanks for all your hard work getting everything in. </p><p><br></p><p>Thank you for completing your application to Dougherty Family College. We are reviewing your application and will reach out to you soon.</p><p><br></p><p>Questions? Contact <a href="https://dfc.stthomas.edu/about/faculty-staff/erica-embury/" target="_blank">Erica Embury</a>, Associate Director of Admissions. She&#39;d love to hear from you!</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationPortal','Complete App','','','','','','','Fall 2024','2023-08-15T20:06:01.000+0000','Graphic: UG Complete (DFC)','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-9');
