INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-161','Inactive','2022-08-02T03:50:44.000+0000','','<p><strong style="background-color: rgb(255, 255, 255); font-size: 18px; color: rgb(68, 68, 68);">Welcome to the DFC Application!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"></p>','','ApplicationPortal','Started App','','','','','','','','2022-09-07T18:34:23.000+0000','Graphic: UG Finish App (DFC)','','<center><iframe src="https://player.vimeo.com/video/360362442" width="570" height="291" frameborder="0" allow="autoplay; fullscreen" allowfullscreen></iframe></center><br><hr style="width:100%;margin-left:auto;margin-right:auto;border-top:1px solid#7030A0;height:3px;border-bottom:1px solid#7030A0;border-left: 1px solid#fff"></hr><br><Font color="#6d3696"> <Font size="4"><b>What else should you do?</b></Font></Font></br><body><br><p>•<a href="https://dfc.stthomas.edu/visit/"> Visit!</a></p><br><p>•<a href="https://www.stthomas.edu/admissions/undergraduate/contact/locate-counselor"> Meet your admissions counselor</a></br></p><br><p>•<a href="https://dfc.stthomas.edu/aboutus/"> About the college</a></p></br><p>•<a href="https://dfc.stthomas.edu/academics/"> Academics</a></p>','2.0','','','Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-9');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-162','Active','2022-08-02T03:50:44.000+0000','Status: Waitlist','<p style="text-align: center;"></p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;Other','ApplicationPortal','Deferred Admit','','','','','','','','2023-01-31T21:49:48.000+0000','Graphic: UG Waitlist (DFC)','','','','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-9');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-163','Active','2022-08-02T03:50:44.000+0000','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations on being admitted to </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Dougherty Family College!</strong></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">We are excited to have you join our community and the incoming cohort for Fall 2023. There’s a lot of information we’d like to share with you, but below are the most important items to note moving forward.</span></p><p><br></p><p><strong style="color: rgb(109, 54, 150); font-size: 16px;">Financial Aid</strong></p><p><span style="font-size: 16px;">If you have not done so already, you should apply for financial aid as soon as possible. Offers of admission to the Dougherty Family College are conditioned on an applicant’s demonstration that they have sufficiently high financial need to qualify for institutional aid. Please feel free to contact </span><a href="https://dfc.stthomas.edu/about/faculty-staff/erica-embury/#_ga=2.27702972.1256893308.1686664130-113324796.1670349734" target="_blank" style="font-size: 16px;">Erica Embury</a><span style="font-size: 16px;"> – Associate Director of Admissions </span><span style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">– </span><span style="font-size: 16px;">with questions. She can be reached at (651) 962-8013 or erica.embury@stthomas.edu for information on applying for financial aid. You should apply for financial aid as soon as possible. Detailed information pertaining to your financial aid will be mailed to you shortly after you are admitted.</span></p>','','ApplicationPortal','Admit','','','','','','','Spring 2024;Fall 2024','2023-08-16T21:18:22.000+0000','Graphic: UG Admit (DFC)','','','6.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-9');
