INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-177','Active','2022-09-07T16:12:15.000+0000','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Welcome to the Dougherty Family College Application!</strong></p><p><br></p><p>Thank you for starting your application to Dougherty Family College! We review applications on a rolling basis. Space in our class is limited, so please complete your application as soon as possible. To have a complete application on file, you must submit your high school transcript.</p>','U.S. Citizen;U.S. Dual Citizen;U.S. Permanent Resident;Asylee/Refugee;International;Other','ApplicationPortal','Started App','','','','','','','','2023-06-13T22:02:12.000+0000','Graphic: DFC Started App (DFC)','','','5.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-9');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-178','Active','2022-09-07T18:38:33.000+0000','','<p><strong style="color: rgb(109, 54, 150);">Transcripts</strong></p><p><br></p><p>Transcripts can be emailed or mailed to us at:</p><p><br></p><p><strong>Email: </strong>admissions@stthomas.edu</p><p><br></p><p><strong>Mail: </strong></p><p>University of St. Thomas</p><p>Office of Admissions</p><p>Mail 5017</p><p>2115 Summit Avenue</p><p>St. Paul, MN 55105-1096</p><p><br></p><p>Transcripts can also be sent electronically through Parchment/Naviance to the University of St. Thomas.</p><p><br></p><p>We will accept unofficial transcripts for your application. You may submit an unofficial transcript by downloading it from your school system and sending it to admissions@stthomas.edu or your admissions counselor.</p>','','ApplicationPortal','Started App;Submitted App','','','','','','','','2023-06-13T22:18:08.000+0000','Submit Transcripts (DFC)','UGFRSubmitTranscripts','','20.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-9');
