INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-188','Active','2022-08-02T03:50:44.000+0000','','','','ApplicationPortal','Started App','','','','','','','','2023-07-17T15:16:47.000+0000','Pre-Checklist Text BETA (Francis) (UGFR)','','<div class="USTExitButton">

    <div class="animated-text">

        <div class="Welcome">

            <b>Welcome to the St. Thomas Application! 🎉</b>

        </div>

        <div class="Welcome">

            <b>Please begin your application to view specific requirements.</b>

        </div>

