    <button onclick="webOnlyAlert_closeClicked()" aria-label="Close" id="close__message" class="closeButton" style="color:#fff;">

        <strong>X</strong>

    </button>

</div>

<script type="text/javascript">

    document.addEventListener(''DOMContentLoaded'', function () {

        if (!webOnlyAlert_readCookie("hide_alert_message")) {

            document.querySelector(''.USTExitButton'').closest(''.slds-card'').style.display = ''block'';

        } else {

            document.querySelector(''.USTExitButton'').closest(''.slds-card'').style.display = ''none'';

        }

    });

    function webOnlyAlert_createCookie(cname, cvalue, exdays) {

        const d = new Date();

        d.setTime(d.getTime() + (exdays * 24 * 60 * 60 * 1000));

        let expires = "expires=" + d.toUTCString();

        document.cookie = cname + "=" + cvalue + ";" + expires + ";path=/";

    }

    function webOnlyAlert_readCookie(a) {

        // eslint-disable-next-line

        const b = document.cookie.match("(^|[^;]+)\\s*" + a + "\\s*=\\s*([^;]+)");

        return b ? b.pop() : false;

    }

    function webOnlyAlert_closeClicked() {

        webOnlyAlert_createCookie("hide_alert_message", true, 1); // cookie will live for 1 hour. the value is data.exp in the original, allowing the expiration date to come from the JSON object, but I broke that here.

        document.querySelector(''.USTExitButton'').closest(''.slds-card'').style.display = ''none'';

    }

</script>

