INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-191','Active','2022-08-02T03:50:44.000+0000','','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Welcome to the International First-Year Application! </strong></p><p><br></p><p>Thank you for beginning your application. <span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">Use the Application Portal above to follow the steps to submit your application. For questions, contact your </span><a href="https://www.stthomas.edu/admissions/undergraduate/contact/" target="_blank" style="background-color: rgb(255, 255, 255);">admissions counselor</a>. You can find more details on the <a href="https://www.stthomas.edu/admissions/international-students/application-information/" target="_blank">International Admissions website</a>.</p><p><br></p><p><strong style="color: rgb(109, 54, 150);">Application Timelines </strong></p><p><span style="background-color: rgb(255, 255, 255); color: rgb(68, 68, 68);">All international student applications are reviewed on a rolling basis. Admission decisions will generally be issued within two weeks of receiving a complete application. </span></p>','International','ApplicationPortal','Started App','','','','','','','','2022-12-01T18:45:19.000+0000','Graphic: UG Started INTL (UGFR)','GraphicUGStartedNTLUGFR','','2.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-10');
