INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-211','Active','2022-09-27T18:27:38.000+0000','Status: Accepted','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations! </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">What&#39;s next? Please complete your Intent to Enroll form to confirm your enrollment.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationPortal','Admit','','','','','','','','2022-10-31T17:03:50.000+0000','Graphic: GR Admit (GSSW)','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-21');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-212','Active','2022-09-27T18:27:38.000+0000','Status: Submitted','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(112, 48, 160);">Thank you for submitting your online graduate application.</strong></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;"><span class="ql-cursor">﻿</span>Please review the Application Requirements checklist, and the Next Steps for any additional items needed to complete your enrollment.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions or visit</span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;"> Graduate Student Resources.</a></p>','','ApplicationPortal','Submitted App;Complete App;File Hold','','','','','','','','2022-11-17T21:50:58.000+0000','Graphic: GR View Submitted (GSSW)','','','1.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-21');
