INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-248','Active','2022-12-20T20:36:35.000+0000','','<p><strong style="color: rgb(109, 54, 150); font-size: 20px;">Welcome to the Bachelor of Science in Nursing Application!</strong></p><p><br></p><p><em style="font-size: 16px;">Please use your St. Thomas (non-vanity) email address for your application: username@stthomas.edu. Ex: </em><em style="font-size: 16px; color: rgb(0, 0, 0);">xxxx0001@stthomas.edu</em><em style="font-size: 16px;">.</em></p>','','ApplicationCreate;ApplicationRegistration','','','','','','','','','2023-01-27T21:48:01.000+0000','Welcome (UGBSN)','','','0.0','','','Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-24');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-249','Active','2023-01-03T15:20:25.000+0000','Status: Submitted','<p style="text-align: center;"><strong style="color: rgb(112, 48, 160); font-size: 20px;">Thank you for submitting your online application.</strong></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the School of Nursing at </span><a href="mailto:nursing@stthomas.edu" target="_blank" style="font-size: 16px;">nursing@stthomas.edu</a><span style="font-size: 16px;">. </span></p>','','ApplicationPortal','Submitted App;Complete App;File Hold','','','','','','','','2023-01-03T15:20:25.000+0000','Graphic: UG View Submitted (UGBSN)','','','1.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-24');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-250','Inactive','2022-09-27T18:27:38.000+0000','','<p style="text-align: center;"><strong style="font-size: 16px;">Thank you for submitting your online graduate application.</strong></p><p><br></p><p><span style="font-size: 16px;">Please review the Application Requirements checklist, and any additional items needed to complete your enrollment.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the </span><a href="" target="_blank" style="font-size: 16px;">Graduate Office of Admissions</a><span style="font-size: 16px;">, or visit </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationPortal','Submitted App;Complete App;File Hold','','','','','','','','2022-11-17T21:50:58.000+0000','Graphic: DSW View Submitted (GSSW)','','','','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-21');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-251','Active','2022-09-27T18:27:38.000+0000','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Next Steps for DSW</strong></p><p><br></p><p><br></p><p><strong style="font-size: 16px;">The DSW</strong><span style="font-size: 16px;"> requires a bachelor’s degree from a regionally accredited U.S. institution (or the international equivalent). and a master&#39;s degree from an MSW program accredited by the Council on Social Work Education (CSWE). Original transcripts are required from all undergraduate and graduate institutions you have attended, sent directly from the institution. If your institution offers electronic transcripts, please send them to </span><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">gradadmissions@stthomas.edu</a><span style="font-size: 16px;">. Paper transcripts must be submitted in sealed envelopes and signed by the appropriate university official. These can be sent to:</span></p><p><br></p><p><strong style="font-size: 16px;">University of St. Thomas</strong></p><p><strong style="font-size: 16px;">Graduate Records - Admissions</strong></p><p><strong style="font-size: 16px;">1000 LaSalle Ave., Box 5</strong></p><p><strong style="font-size: 16px;">Minneapolis, MN 55403-2005</strong></p><p><br></p><p><em style="font-size: 16px;">Exception: Transcripts for advanced placement courses and study abroad transfer credits are not required.</em></p><p><br></p><p><span style="font-size: 16px;">It is recommended that international students complete applications to the evaluation service at least six months prior to the term in which they wish to start the program. We accept evaluations from the following; please work with one of them to obtain your evaluation. </span></p><p><a href="http://www.wes.org/" target="_blank" style="font-size: 16px;">World Education Services</a></p><p><a href="http://www.ece.org/" target="_blank" style="font-size: 16px;">Educational Credential Evaluators</a></p><p><br></p><p><span style="font-size: 16px;">International students may be required to submit additional supplemental documents.</span></p><p><br></p><p><span style="font-size: 16px;">Please visit our website for a full listing of international requirements: </span><a href="https://www.stthomas.edu/socialwork/dsw/admission/application/internationalapplicants/" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">https://www.stthomas.edu/socialwork/dsw/admission/application/internationalapplicants/</a></p><p><br></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">HEA Student Consumer Information</strong></p><p><span style="font-size: 16px;">The following site is provided as a resource to prospective and enrolled students and their parents, and lists the HEA required disclosures by the University of St. Thomas: </span><a href="https://www.stthomas.edu/policies/required-student-disclosures" target="_blank" style="font-size: 16px; background-color: rgb(255, 255, 255);">https://www.stthomas.edu/policies/required-student-disclosures</a></p>','','ApplicationPortal','Submitted App;Complete App;File Hold','','','','','','','','2022-11-17T21:49:22.000+0000','DSW Next Steps (GSSW)','','','6.0','','','Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-21');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-252','Active','2022-11-01T17:33:11.000+0000','Status: Confirmed','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations! </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">Thank you for submitting your Intent to Enroll. Please watch your email for further communications on next steps.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationPortal','Confirmed','','','','','','','','2022-11-02T16:00:00.000+0000','Graphic: GR Confirmed (GSPP)','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-253','Active','2022-11-01T20:50:59.000+0000','Status: Withdrawn After Accept','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations! </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">Thank you for submitting your Intent to Enroll and letting us know you do not intend to attend St. Thomas. Please contact us if anything changes. </span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationPortal','Withdrawn','After Accept','','','','','','','2022-11-01T20:50:59.000+0000','Graphic: GR Withdrawn After Accept (GSPP)','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-254','Active','2022-11-02T16:00:21.000+0000','Status: Under Review','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations! </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">Thank you for submitting your Intent to Enroll. Please watch your email for further communications on next steps.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationPortal','Admit','Needs Review','','','','','','','2022-11-02T16:00:21.000+0000','Graphic: GR Admit Needs Review (GSPP)','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-22');
