INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-288','Active','2022-11-01T17:30:58.000+0000','Status: Confirmed','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations! </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">Thank you for submitting your Intent to Enroll. Please watch your email for further communications on next steps.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationPortal','Confirmed','','','','','','','','2022-11-02T16:01:46.000+0000','Graphic: GR Confirmed (GSOEd)','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-16');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-289','Active','2022-11-01T20:56:47.000+0000','Status: Withdrawn After Accept','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations! </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">Thank you for submitting your Intent to Enroll and letting us know you do not intend to attend St. Thomas. Please contact us if anything changes. </span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationPortal','Withdrawn','After Accept','','','','','','','2022-11-01T20:56:47.000+0000','Graphic: GR Withdrawn After Accept (GSOEd)','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-16');
