INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-318','Active','2022-09-27T18:27:38.000+0000','Status: Submitted','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(112, 48, 160);">Thank you for submitting your online graduate application.</strong></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;"><span class="ql-cursor">﻿</span>Please review the Application Requirements checklist, and the Next Steps for any additional items needed to complete your enrollment.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions or visit</span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;"> Graduate Student Resources.</a></p>','','ApplicationPortal','Submitted App;Complete App;File Hold','','','','','','','','2022-11-17T21:50:58.000+0000','Graphic: GR View Submitted (GLAW)','','','1.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-18');
