INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-342','Active','2022-09-27T18:27:38.000+0000','Status: Accepted','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations! </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">What&#39;s next? Please complete your Intent to Enroll form to confirm your enrollment.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationPortal','Admit','','','','','','','','2022-10-31T17:14:55.000+0000','Graphic: GR Admit (GSOE)','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-19');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-343','Active','2022-09-27T18:27:38.000+0000','','<p><strong style="color: rgb(109, 54, 150); font-size: 18px;">Next Steps for Graduates</strong></p><p><br></p><p><br></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Transcripts</strong></p><p><strong style="font-size: 16px;">We require a bachelor’s degree from a regionally accredited U.S. institution (or the international equivalent).</strong><span style="font-size: 16px;"> Original transcripts are required from all undergraduate and graduate institutions you have attended, sent directly from the institution. If your institution offers electronic transcripts, please send them to </span><a href="mailto:gradadmissions@stthomas.edu" target="_blank" style="font-size: 16px;">gradadmissions@stthomas.edu</a><span style="font-size: 16px;">. Paper transcripts must be submitted in sealed envelopes and signed by the appropriate university official. These can be sent to: </span></p><p><br></p><p><strong style="font-size: 16px;">University of St. Thomas</strong></p><p><strong style="font-size: 16px;">Graduate Records - Admissions</strong></p><p><strong style="font-size: 16px;">1000 LaSalle Ave., Box 5</strong></p><p><strong style="font-size: 16px;">Minneapolis, MN 55403-2005</strong></p><p><br></p><p><em style="font-size: 16px;">Exception: Transcripts for advanced placement courses and study abroad transfer credits are not required.</em></p><p><br></p><p><span style="font-size: 16px;">It is recommended that international students complete applications to the evaluation service at least six months prior to the term in which they wish to start the program. We accept evaluations from the following; please work with one of them to obtain your evaluation. </span></p><p><a href="http://www.wes.org/" target="_blank" style="font-size: 16px;">World Education Services</a></p><p><a href="http://www.ece.org/" target="_blank" style="font-size: 16px;">Educational Credential Evaluators</a></p><p><br></p><p><span style="font-size: 16px;">International students may be required to submit additional supplemental documents.</span></p><p><br></p><p><span style="font-size: 16px;">Please visit our website for a full listing of international requirements: </span><a href="https://www.stthomas.edu/intl/graduate/" target="_blank" style="font-size: 16px;">https://www.stthomas.edu/intl/graduate/</a><span style="font-size: 16px;"> </span></p><p><span style="font-size: 16px;"> </span></p><p><strong style="font-size: 16px; color: rgb(109, 54, 150);">HEA Student Consumer Information</strong></p><p><span style="font-size: 16px;">The following site is provided as a resource to prospective and enrolled students and their parents, and lists the HEA required disclosures by the University of St. Thomas:</span><strong style="font-size: 16px;"> </strong><a href="https://www.stthomas.edu/policies/required-student-disclosures" target="_blank" style="font-size: 16px;">https://www.stthomas.edu/policies/required-student-disclosures</a><span style="font-size: 16px;"> </span></p>','','ApplicationPortal','Submitted App;Complete App;File Hold','','','','','','','','2022-11-17T21:49:22.000+0000','Graduate Next Steps (GSOE)','','','5.0','','','Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-19');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-344','Active','2022-09-27T18:27:38.000+0000','','<p><br></p><p><br></p>','','ApplicationPortal','Admit','','','','','','','','2022-10-31T17:01:42.000+0000','Yes You''re In (GSOE)','','<div class="containerUSTGrad">

  <span class="textUSTGrad"><center><b>Yes! You''re In!</b></center></span>

</div>



<style>



.containerUSTGrad{

  position: absolute;

  top: 50%;

  left: 50%;

  transform: translate(-50%, -50%);

  width: 100%;

}



.containerUSTGrad span{

  color: #6d3696 ;

  text-transform: uppercase;

  display: block;

}

.textUSTGrad{

  font-size: 20px;

  font-weight: 700;

  margin-bottom: 20px;

  position: relative;

  animation: text 3s 1;

}



@keyframes text {

  0%{

    color: white;

    margin-bottom: -40px;

  }

  30%{

    letter-spacing: 25px;

    margin-bottom: -40px;

  }

  85%{

    letter-spacing: 8px;

    margin-bottom: -40px;

  }

}



