INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-345','Active','2022-10-07T21:47:25.000+0000','','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Welcome to Graduate Programs in Engineering &amp; Software!</strong></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px; font-family: Calibri, Arial, Helvetica, sans-serif; color: rgb(0, 0, 0);">Thank you for starting an application to Graduate Programs in Engineering &amp; Software! For questions about the application or our programs, please contact our Graduate Student Services team at 651-962-5500 or </span><a href="mailto:gradengineering@stthomas.edu" target="_blank" style="color: rgb(0, 120, 215); font-size: 16px; font-family: Calibri, Arial, Helvetica, sans-serif;">gradengineering@stthomas.edu</a><span style="font-size: 16px; font-family: Calibri, Arial, Helvetica, sans-serif; color: rgb(0, 0, 0);">.</span></p>','','ApplicationCreate;ApplicationRegistration','','','','','','','','','2023-06-26T21:36:29.000+0000','Welcome (GSOE)','','','0.0','','','Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-19');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-346','Active','2022-11-01T17:08:52.000+0000','Status: Confirmed','<p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">Congratulations! </strong></p><p style="text-align: center;"><strong style="font-size: 20px; color: rgb(109, 54, 150);">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px;">Thank you for submitting your Intent to Enroll. Please watch your email for further communications on next steps.</span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationPortal','Confirmed','','','','','','','','2022-11-02T21:25:12.000+0000','Graphic: GR Confirmed (GCAS)','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-20');
INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-347','Active','2022-11-01T19:01:26.000+0000','Status: Withdrawn After Accept','<p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">Congratulations! </strong></p><p style="text-align: center;"><strong style="color: rgb(109, 54, 150); font-size: 20px;">You have been accepted to the University of St. Thomas!</strong></p><p style="text-align: center;"><br></p><p style="text-align: center;"><br></p><p><span style="font-size: 16px; color: rgb(68, 68, 68);">Thank you for submitting your Intent to Enroll and letting us know you do not intend to attend St. Thomas. Please contact us if anything changes. </span></p><p><br></p><p><span style="font-size: 16px;">Questions? Contact the Graduate Office of Admissions, or </span><a href="https://www.stthomas.edu/admissions/graduate/financialaidstudentresources/" target="_blank" style="font-size: 16px;">visit Graduate Student Resources</a><span style="font-size: 16px;">.</span></p>','','ApplicationPortal','Withdrawn','After Accept','','','','','','','2022-11-01T19:01:26.000+0000','Graphic: GR Withdrawn After Accept (GCAS)','','','2.0','','','Content Top','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-20');
