INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-358','Active','2022-12-01T18:45:45.000+0000','','<p><strong style="font-size: 18px; color: rgb(109, 54, 150);">Missing Documents</strong></p><p><br></p><p><span style="font-size: 16px;">Please email your missing documents to </span><a href="mailto:international@stthomas.edu" target="_blank" style="font-size: 16px; color: rgb(68, 68, 68); background-color: rgb(255, 255, 255);">international@stthomas.edu</a><span style="font-size: 16px;">. To view required documents, visit the International Admissions </span><a href="https://www.stthomas.edu/admissions/international-students/application-information/index.html" target="_blank" style="font-size: 16px;">website</a><span style="font-size: 16px;">. </span></p><p><br></p><p><span style="font-size: 16px;">Missing documents can also be mailed to: </span></p><p><br></p><p><span style="font-size: 16px;">University of St. Thomas</span></p><p><span style="font-size: 16px;">Office of International Students &amp; Scholars</span></p><p><span style="font-size: 16px;">Mail 5014</span></p><p><span style="font-size: 16px;">2115 Summit Avenue</span></p><p><span style="font-size: 16px;">St. Paul, MN 55105-1096</span></p><p><br></p><p><span style="font-size: 16px;">We will accept unofficial transcripts for your application. Students must have official transcripts upon arrival to St. Thomas. </span></p>','International','ApplicationPortal','Started App;Submitted App;Temporary Hold','','','','','','','','2023-01-27T18:23:03.000+0000','Submit Missing Docs INTL (UGFRCA)','UGFRSubmitMissingDocssINTL','','20.0','','','Content Bottom','Central Daylight Time (America/Chicago)','Custom','Application_Control__c-13');
