    .USTblock__social__svgINSTA {

        right: 1px;

    }

    .USTblock__social__svgTIKTOK {

        right: -1px;

    }

    .USTSocialMediaIcons li a:before {

        position: absolute;

        content: '''';

        top: 0;

        left: 0;

        height: 100%;

        width: 100%;

        border-radius: 50%;

        z-index: -1;

        transform: scale(0.9);

    }

    .USTSocialMediaIcons li a:hover:before {

        transform: scale(1.9);

    }

    .USTSocialMediaIcons li a:hover:before {

        filter: blur(3px);

        transform: scale(1.2);

       /* box-shadow: 0 0 15px #6f3d99; */

    }

    .USTSocialMediaIcons a:hover {

        fill: #ffa500;

