        text-shadow: 0 0 15px #6f3d99;

        */

    }

    .USTSocialMediaIcons li {

        border-bottom: 5px transparent solid;

    }

    .USTSocialMediaIcons li:hover {

        border-bottom: 5px purple solid;

    }

    /*

    .USTSocialMediaIcons a:hover {

        content: '''';

        background-color: blue;

        height: 5px;

