INSERT INTO "EASY_Widget__c" VALUES('EASY_Widget__c-389','Active','2022-09-29T19:29:38.000+0000','','<p><strong style="font-size: 16px; color: rgb(109, 54, 150);">Admission Decision Timeline</strong></p>','','ApplicationPortal','Complete App;File Hold;Pending;Denied','','','','','','','','2022-12-15T18:51:14.000+0000','Admissions Decisions Dates (UGFRCA)','UGFRAdmissionsDecisionsDates','<style>

    .lineUST {

        border-bottom: 5px solid #5f19a0;

        margin-top: 5px;

        margin-bottom: 4px;

        width: 100%;

    }



</style>

<div class="lineUST"></div>









<div class="hwrapUST"><div class="hmoveUST">

<div class="hslideUST">

<div class="dynamic-txtsUST"><h3><i>First-Year</i></h3>

<div class="animationUST">

<br>

<p><span class="firstUST"><b>By Dec. 15</b></span>

<span class="slideUST">

<p><span class="secondUST">- If applied by Nov. 1</p></p>

<p><span class="firstUST"><b>By Feb. 15</b></span></span>

<span class="slideUST">

<p><span class="secondUST">- If applied by Jan. 15</p></p></span></span>

<p><span class="firstUST"><b>After Feb. 15</b></span>

<span class="slideUST"> 

<p><span class="secondUST">- Decisions are made on a rolling basis. Usually, you’ll hear back from us within 2-3 weeks of submitting all required documents.</p></p></span></span>

</div>

</div>

</div>



<div class="hslideUST">

<div class="dynamic-txtsUST"><h3><i>International First-Year</i></h3>

<div class="animationUST">

<br>

<p><span class="firstUST">You will receive an admission decision by email within approximately 2 weeks after submitting all required documents.</p></span>

</div>

</div>

</div>

</div></div>



<style>



.dynamic-txtsUST{

color: #6d3696;

}



.animationUST{

animation: fadeIn 1s forwards;

transition-timing-function: cubic-bezier(0.785, 0.135, 0.15, 0.86);

}



.firstUST{

display: inline-block;

position: relative;

z-index: 1;

}



.slideUST{

display: inline-flex;

overflow: hidden;

}



.secondUST{

font-weight: 100;

z-index: -1;

display: inline-block;

animation: secondspan 1.5s forwards cubic-bezier(0.785, 0.135, 0.15, 0.86);

}



@keyframes fadeIn{



0%{

opacity: 0;

transform: scale(0);

}



50%{

opacity: 1;

transform: scale(1);

}



0%{

opacity: 1;

transform: scale(0.5);

}



}





@keyframes secondspan{



0%{

transform: translateX(-900%);

}



60%{

transform: translateX(-100%);

}



100%{

transform: translateX(0%);

}



}



.hwrapUST{

width: 100%;

overflow: hidden;

}



.hmoveUST{

display: flex;

position: relative;

top: 0;

right: 0;

}



.hslideUST{

width: 100%;

