INSERT INTO "Question__c" VALUES('Question__c-683','true','','','','Started App;Submitted App','','','','','2022-09-27T18:27:56.000Z','false','Non-Degree','','','','1.0','false','true','Started App','false','','','','','','','false','','2025-04-11T15:22:13.000Z','','','','MSW Non-Degree Course Selection (GSSW)','Name','false','','','','','','','','','QuestionUuid-4d36517c-aa07-4dbb-a478-544b62adc627','','012DS00000AdtxdYAB','','','','','<p>After receiving your application, the MSW Program Manager will follow up with you to select a course from eligible courses.</p><p><br></p><p>Course meeting times and details can be found at www.stthomas.edu/classes.</p><p><br></p><p>Please note that courses are also subject to space availability.</p>','','','','Requirement_Item__c-157');
