INSERT INTO "Question__c" VALUES('Question__c-1116','true','','','','','','','','','2022-11-01T19:34:53.000Z','false','','','','','2.0','false','true','','false','','','','','','','false','','2025-04-11T15:22:14.000Z','','','','Confirmation Deposit Enticement (DFC)','Name','false','','','','','','','','','QuestionUuid-ad66aeb8-2acd-4eae-bda0-9918dc7aa403','','012DS00000AdtxdYAB','','','','','<p>Take your next step to becoming a Tommie!</p><p><br></p><p><em style="font-size: 14px;">To reserve your place in the class you must submit a $50 confirming deposit as soon as possible. Space in the class is limited and will be awarded on a first come, first served basis.</em></p>','','','','Requirement_Item__c-458');
INSERT INTO "Question__c" VALUES('Question__c-1117','true','','','','','','','','','2022-11-01T19:36:03.000Z','false','','','','','2.0','false','true','','false','','','','','','','false','Confirmation Deposit Received','2025-04-11T15:22:14.000Z','','','','Confirmation Deposit Received (DFC)','Name','false','','','','','','','','','QuestionUuid-8171daea-c0a2-480c-aa70-fadd66322d62','','012DS00000AdtxdYAB','','','','','<p><span style="background-color: rgb(255, 255, 255); font-size: 14.6667px; color: rgb(36, 36, 36);">We’re excited to have you join our community of scholars and move one step closer to accomplishing your goals! We promise to be a community that welcomes, appreciates, supports, empowers and challenges you to be a morally responsible leader who thinks critically, acts wisely and works skillfully to advance the common good.</span></p>','','','','Requirement_Item__c-458');
