INSERT INTO "Question__c" VALUES('Question__c-1334','true','','','','','','','','','2022-09-27T18:27:54.000Z','false','','','','','1.0','false','true','','false','','','','','','','false','','2025-04-11T15:22:11.000Z','','','','Courses in Progress static(GSPP)','Name','false','','','','','','','','','QuestionUuid-f8a85ea7-9a2f-4e4e-bd9a-8c1ae105d998','','012DS00000AdtxdYAB','','','','','<p>If you have course(s) in progress which will not show up on your transcript, or courses for which you will be registering, please enter the following information in the space provided:</p><ul><li>Course Title(s)</li><li>Course Number(s)</li><li>Instructor&#39;s Name(s)</li><li>Start/End Dates</li></ul>','','','','Requirement_Item__c-204');
INSERT INTO "Question__c" VALUES('Question__c-1335','false','','','','Started App;Submitted App','','','','','2022-09-27T18:28:02.000Z','false','','','','','23.0','false','true','Started App','false','','','','','','','false','','2025-04-11T15:22:11.000Z','','','','ESL Authorization Statement(GSPP)','Name','false','','','','','','','','','QuestionUuid-c68aa27b-1a68-4cd7-a44c-431b20d2faed','','012DS00000AdtxdYAB','','Started App','','','I authorize St. Thomas to share all of the information I am submitting as part of this application with ELS Educational Services, Inc., which will automatically consider me for admission to the St. Thomas Pathway Program if I am not eligible for direct admission to the University of St. Thomas. I understand that if I do not authorize St. Thomas to share information with ELS, ELS will not consider me for admission to the St. Thomas Pathway Program.','','','','Requirement_Item__c-200');
