INSERT INTO "Question__c" VALUES('Question__c-1464','true','','','','Started App;Submitted App','','','','','2023-01-04T18:28:29.000Z','false','','','','','3.0','false','true','Started App','false','','','','','','','false','','2025-04-11T15:22:09.000Z','','','','EJ Scholarship Static topic 400 words (GSSW)','Name','false','','','','','','','','','QuestionUuid-9f73a048-6087-4588-a955-4e97a47dae6d','','012DS00000AdtxdYAB','','','','','<p><span style="font-size: 16px;">In no more than 400 words, identify the general topic you’re interested in pertaining to environmental justice and/or planetary health and why this is important. What question(s) might you seek to answer through your research? How does this relate to social work practice and/or social work education? </span></p>','','','','Requirement_Item__c-188');
