INSERT INTO "Question__c" VALUES('Question__c-1722','true','','','','','','','','','2022-08-02T03:51:30.000Z','false','','','','','0.0','false','true','','false','','','','','','','false','Application Experience Feedback','2025-04-11T15:22:09.000Z','','','','Applicant Feedback Static (DFC)','Name','false','','','','','','','','','QuestionUuid-121b2289-0595-4231-b78c-938912c3b327','','012DS00000AdtxdYAB','','','','','<p><span style="font-size: 15.6px; color: rgb(3, 45, 96);">We are interested in hearing about your experience with our online application. We appreciate your feedback. Thank you.</span></p>','','','','Requirement_Item__c-22');
