INSERT INTO "Question__c" VALUES('Question__c-2280','true','','','','Started App;Submitted App','','','','','2022-12-07T19:10:01.000Z','false','','','','','0.0','false','true','Started App','false','','','','','','','false','Do you intend to live on campus?','2025-04-11T15:22:09.000Z','','','','On-campus housing Static Text(UGTRDFC)','Name','false','','','','','','','','','QuestionUuid-142541b6-05b5-4aa2-b027-1bb164801045','','012DS00000AdtxdYAB','','Started App','','','<p><span style="color: rgb(3, 45, 96);">St. Thomas has a two-year residency requirement policy that requires full-time, undergraduate, first and second-year students to live on campus. To learn more about this policy, including possible exceptions</span>, <a href="https://www.stthomas.edu/residence-life/policies-resources/residency-requirement/index.html" target="_blank">click here.</a></p><p><br></p><p><strong style="color: rgb(3, 45, 96);">Transition DFC students have completed two or more semesters of college/university work and are waived from the residency requirement.</strong></p>','','','','Requirement_Item__c-496');
