INSERT INTO "Question__c" VALUES('Question__c-2355','true','','','','Started App;Submitted App','','','','','2022-09-27T18:28:03.000Z','false','','','','','2.0','false','true','Started App','false','','','','','','','false','','2025-04-11T15:22:10.000Z','','','','Application Materials Consent Text (GOCB)','Name','false','','','','','','','','','QuestionUuid-a6b1ee11-1d87-428b-862e-c8f37f595da3','','012DS00000AdtxdYAB','','Started App','','','<p><strong>Please affirm the following before you submit your application.</strong></p>

