INSERT INTO "Question__c" VALUES('Question__c-3345','true','','','','','','','','','2022-09-27T18:28:04.000Z','false','','','','','0.0','false','true','','false','','','','','','','false','','2025-04-11T15:22:20.000Z','','','','Courses in Progress static(GSOE)','Name','false','','','','','','','','','QuestionUuid-f6aff14c-8ea9-46eb-a480-80e5d5f819a5','','012DS00000AdtxdYAB','','','','','<p>If you have course(s) in progress which will not show up on your transcript, or courses for which you will be registering, please enter the following information in the space provided:</p><ul><li>Course Title(s)</li><li>Course Number(s)</li><li>Instructor&#39;s Name(s)</li><li>Start/End Dates</li></ul>','','','','Requirement_Item__c-319');
