INSERT INTO "Question__c" VALUES('Question__c-3644','true','','','','Confirmed','','','','','2023-03-21T17:41:38.000Z','false','','','','','7.0','false','true','','false','','','Both Deposits Paid','','','','false','','2025-04-11T15:22:15.000Z','','','','Confirmation Confirmation and Housing Deposit Received (UGTR)','Name','false','','','','','','','','','QuestionUuid-d6170732-ebc9-427c-beb1-fc6776203e5a','','012DS00000AdtxdYAB','','','','','<p><strong>Deposit Received</strong></p><p> </p><p>Thanks for submitting your confirmation and housing deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas!</p>','','','','Requirement_Item__c-16');
INSERT INTO "Question__c" VALUES('Question__c-3645','true','','','','Admit','','','','','2023-03-21T17:43:54.000Z','false','','','','','11.0','false','true','','false','','','Select Deposit Type','','','','false','Click the Submit Deposit button below to proceed to our payment processing system.','2025-04-11T15:22:15.000Z','','','','Deposit Confirming Only (UGTR)','Name','false','200.0','First_Year_Undergraduate_Deposit','Confirming Deposit','Custom Amount','','','','','QuestionUuid-50acfd95-841d-41d2-bc1c-20989c796eb1','','012DS00000AdtxXYAR','','','','','','','','','Requirement_Item__c-16');
INSERT INTO "Question__c" VALUES('Question__c-3646','true','','','','Admit','','','','','2023-03-21T17:48:16.000Z','false','','','','','23.0','false','true','','false','','','Housing Deposit Paid','','','','false','','2025-04-11T15:22:15.000Z','','','','Housing Only Deposit Received (UGTR)','Name','false','','','','','','','','','QuestionUuid-c6320305-9902-475f-827c-705cfdaff703','','012DS00000AdtxdYAB','','','','','<p><strong>Deposit Received</strong></p><p> </p><p>Thanks for submitting your housing deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas! Please note we still need your confirming deposit to lock in your spot!</p>','','','','Requirement_Item__c-16');
INSERT INTO "Question__c" VALUES('Question__c-3647','true','','','','Confirmed','','','','','2023-03-21T17:45:07.000Z','false','','','','','13.0','false','true','','false','','','Confirming Deposit Paid','','','','false','','2025-04-11T15:22:15.000Z','','','','Confirming Only Deposit Received (UGTR)','Name','false','','','','','','','','','QuestionUuid-881ad649-9ef7-49f2-8334-d1e64af15d1f','','012DS00000AdtxdYAB','','','','','<p><strong>Deposit Received</strong></p><p> </p><p>Thanks for submitting your confirming deposit and congratulations on making your college decision. We&#39;re so happy you&#39;ve chosen St. Thomas! Please note we still need your housing deposit if you plan to live on campus!</p>','','','','Requirement_Item__c-16');
