INSERT INTO "Question__c" VALUES('Question__c-3649','true','','','','Confirmed','','','','','2023-03-21T18:01:02.000Z','false','','','','','1.0','false','true','','false','','','Confirming Deposit Paid','','','','false','','2025-04-11T15:22:15.000Z','','','','Second Deposit Housing Only Enticement (UGTR)','Name','false','','','','','','','','','QuestionUuid-ab1052e1-b54f-40dd-b536-2dc6622f6ab7','','012DS00000AdtxdYAB','','','','','<p><em>To request your space in our residence halls you must submit a housing deposit.</em></p><p> </p><p>Please note:</p><ul><li>Students admitted to St. Thomas are expected to abide by certain conduct and fulfill obligations. The complete details are <a href="https://www.stthomas.edu/_media-library/_documents/main/admissions-code-of-conduct.pdf" target="_blank">found here</a>.</li><li>The University of St. Thomas requires all students, faculty and staff to be <a href="https://www.stthomas.edu/center-for-well-being/health-requirements/covid-19-vaccine/index.html" target="_blank">vaccinated for COVID-19</a>. Limited exemptions are available for religious and medical reasons.</li></ul><p>Click the Submit Deposit button below to proceed to our payment processing system.</p>','','','','Requirement_Item__c-13');
