INSERT INTO "Question__c" VALUES('Question__c-3680','true','','','','','','','','','2023-05-05T20:35:35.000Z','false','','','','','1.0','false','true','','false','','','','','AP','','false','','2025-04-11T15:22:15.000Z','','','','Self-report Score Option AP (UGFR)','Name','false','','','','','','','','','QuestionUuid-a101d45b-c50c-40de-9d61-6d3764b2ae8e','','012DS00000AdtxdYAB','hed__Test_Type__c','','','','<ol><li><span style="font-size: 16px;">Find the AP exam in the list, enter AP score and date of the exam, and then click “Add Record.” </span></li><li><span style="font-size: 16px;">Click “New Record” and repeat directions above until all AP scores have been entered.  </span></li><li><span style="font-size: 16px;">Click “Save and Continue” only after all AP exam scores have been entered. </span></li></ol><p><span style="font-size: 16px;">Important reminders:</span></p><ul><li><span style="font-size: 16px;">You will be prompted to report any pending AP scores in the Course Preference Form.  </span></li><li><span style="font-size: 16px;">Please remember to submit your official AP score to St. Thomas through the College Board. </span></li></ul><p><br></p>','','','','Requirement_Item__c-31');
