INSERT INTO "Requirement_Item__c" VALUES('Requirement_Item__c-45','True','False','False','','Started App;Submitted App','','','2022-09-27T18:27:51.000+0000','Master''s;Non-Degree','','2.0','True','True','Started App','','','','','','','','<center><b><Font size=4 Font color=#6d3696>Personal Statement</b></Font><Font color=Red>*</Font></center>

<br>

<br>

